00079 /*===   Macros   ===*/
00080 #define MIN(a,b)   ( (a) < (b) ? (a) : (b) )
00081 #define MAX(a,b)   ( (a) > (b) ? (a) : (b) )
00082 #define HASH_FUNCTION(i)         (((i) * 2654435761U) >> ((MINMATCH*8)-LZ4HC_HASH_LOG))
00083 #define DELTANEXTMAXD(p)         chainTable[(p) & LZ4HC_MAXD_MASK]    /* flexible, LZ4HC_MAXD dependent */
00084 #define DELTANEXTU16(table, pos) table[(U16)(pos)]   /* faster */
00085 /* Make fields passed to, and updated by LZ4HC_encodeSequence explicit */
00086 #define UPDATABLE(ip, op, anchor) &ip, &op, &anchor
