00091 static U32 LZ4HC_hashPtr(const void* ptr) { return HASH_FUNCTION(LZ4_read32(ptr)); }
00092 
00093 
00094 /**************************************
00095 *  HC Compression
00096 **************************************/
00097 static void LZ4HC_clearTables (LZ4HC_CCtx_internal* hc4)
00098 {
00099     MEM_INIT(hc4->hashTable, 0, sizeof(hc4->hashTable));
00100     MEM_INIT(hc4->chainTable, 0xFF, sizeof(hc4->chainTable));
00101 }
00102 
00103 static void LZ4HC_init_internal (LZ4HC_CCtx_internal* hc4, const BYTE* start)
00104 {
00105     size_t const bufferSize = (size_t)(hc4->end - hc4->prefixStart);
00106     size_t newStartingOffset = bufferSize + hc4->dictLimit;
00107     assert(newStartingOffset >= bufferSize);  /* check overflow */
00108     if (newStartingOffset > 1 GB) {
00109         LZ4HC_clearTables(hc4);
00110         newStartingOffset = 0;
00111     }
00112     newStartingOffset += 64 KB;
00113     hc4->nextToUpdate = (U32)newStartingOffset;
00114     hc4->prefixStart = start;
00115     hc4->end = start;
00116     hc4->dictStart = start;
00117     hc4->dictLimit = (U32)newStartingOffset;
00118     hc4->lowLimit = (U32)newStartingOffset;
00119 }
00120 
00121 
00122 /* Update chains up to ip (excluded) */
00123 LZ4_FORCE_INLINE void LZ4HC_Insert (LZ4HC_CCtx_internal* hc4, const BYTE* ip)
00124 {
00125     U16* const chainTable = hc4->chainTable;
00126     U32* const hashTable  = hc4->hashTable;
00127     const BYTE* const prefixPtr = hc4->prefixStart;
00128     U32 const prefixIdx = hc4->dictLimit;
00129     U32 const target = (U32)(ip - prefixPtr) + prefixIdx;
00130     U32 idx = hc4->nextToUpdate;
00131     assert(ip >= prefixPtr);
00132     assert(target >= prefixIdx);
00133 
00134     while (idx < target) {
00135         U32 const h = LZ4HC_hashPtr(prefixPtr+idx-prefixIdx);
00136         size_t delta = idx - hashTable[h];
00137         if (delta>LZ4_DISTANCE_MAX) delta = LZ4_DISTANCE_MAX;
00138         DELTANEXTU16(chainTable, idx) = (U16)delta;
00139         hashTable[h] = idx;
00140         idx++;
00141     }
00142 
00143     hc4->nextToUpdate = target;
00144 }
00145 
00148 LZ4_FORCE_INLINE
00149 int LZ4HC_countBack(const BYTE* const ip, const BYTE* const match,
00150                     const BYTE* const iMin, const BYTE* const mMin)
00151 {
00152     int back = 0;
00153     int const min = (int)MAX(iMin - ip, mMin - match);
00154     assert(min <= 0);
00155     assert(ip >= iMin); assert((size_t)(ip-iMin) < (1U<<31));
00156     assert(match >= mMin); assert((size_t)(match - mMin) < (1U<<31));
00157     while ( (back > min)
00158          && (ip[back-1] == match[back-1]) )
00159             back--;
00160     return back;
00161 }
00162 
00163 #if defined(_MSC_VER)
00164 #  define LZ4HC_rotl32(x,r) _rotl(x,r)
00165 #else
00166 #  define LZ4HC_rotl32(x,r) ((x << r) | (x >> (32 - r)))
00167 #endif
00168 
00169 
00170 static U32 LZ4HC_rotatePattern(size_t const rotate, U32 const pattern)
00171 {
00172     size_t const bitsToRotate = (rotate & (sizeof(pattern) - 1)) << 3;
00173     if (bitsToRotate == 0) return pattern;
00174     return LZ4HC_rotl32(pattern, (int)bitsToRotate);
00175 }
00176 
00177 /* LZ4HC_countPattern() :
00178  * pattern32 must be a sample of repetitive pattern of length 1, 2 or 4 (but not 3!) */
00179 static unsigned
00180 LZ4HC_countPattern(const BYTE* ip, const BYTE* const iEnd, U32 const pattern32)
00181 {
00182     const BYTE* const iStart = ip;
00183     reg_t const pattern = (sizeof(pattern)==8) ?
00184         (reg_t)pattern32 + (((reg_t)pattern32) << (sizeof(pattern)*4)) : pattern32;
00185 
00186     while (likely(ip < iEnd-(sizeof(pattern)-1))) {
00187         reg_t const diff = LZ4_read_ARCH(ip) ^ pattern;
00188         if (!diff) { ip+=sizeof(pattern); continue; }
00189         ip += LZ4_NbCommonBytes(diff);
00190         return (unsigned)(ip - iStart);
00191     }
00192 
00193     if (LZ4_isLittleEndian()) {
00194         reg_t patternByte = pattern;
00195         while ((ip<iEnd) && (*ip == (BYTE)patternByte)) {
00196             ip++; patternByte >>= 8;
00197         }
00198     } else {  /* big endian */
00199         U32 bitOffset = (sizeof(pattern)*8) - 8;
00200         while (ip < iEnd) {
00201             BYTE const byte = (BYTE)(pattern >> bitOffset);
00202             if (*ip != byte) break;
00203             ip ++; bitOffset -= 8;
00204     }   }
00205 
00206     return (unsigned)(ip - iStart);
00207 }
00208 
00209 /* LZ4HC_reverseCountPattern() :
00210  * pattern must be a sample of repetitive pattern of length 1, 2 or 4 (but not 3!)
00211  * read using natural platform endianness */
00212 static unsigned
00213 LZ4HC_reverseCountPattern(const BYTE* ip, const BYTE* const iLow, U32 pattern)
00214 {
00215     const BYTE* const iStart = ip;
00216 
00217     while (likely(ip >= iLow+4)) {
00218         if (LZ4_read32(ip-4) != pattern) break;
00219         ip -= 4;
00220     }
00221     {   const BYTE* bytePtr = (const BYTE*)(&pattern) + 3; /* works for any endianness */
00222         while (likely(ip>iLow)) {
00223             if (ip[-1] != *bytePtr) break;
00224             ip--; bytePtr--;
00225     }   }
00226     return (unsigned)(iStart - ip);
00227 }
00228 
00229 /* LZ4HC_protectDictEnd() :
00230  * Checks if the match is in the last 3 bytes of the dictionary, so reading the
00231  * 4 byte MINMATCH would overflow.
00232  * @returns true if the match index is okay.
00233  */
00234 static int LZ4HC_protectDictEnd(U32 const dictLimit, U32 const matchIndex)
00235 {
00236     return ((U32)((dictLimit - 1) - matchIndex) >= 3);
00237 }
00238 
00239 typedef enum { rep_untested, rep_not, rep_confirmed } repeat_state_e;
00240 typedef enum { favorCompressionRatio=0, favorDecompressionSpeed } HCfavor_e;
00241 
00242 LZ4_FORCE_INLINE int
00243 LZ4HC_InsertAndGetWiderMatch (
00244         LZ4HC_CCtx_internal* const hc4,
00245         const BYTE* const ip,
00246         const BYTE* const iLowLimit, const BYTE* const iHighLimit,
00247         int longest,
00248         const BYTE** matchpos,
00249         const BYTE** startpos,
00250         const int maxNbAttempts,
00251         const int patternAnalysis, const int chainSwap,
00252         const dictCtx_directive dict,
00253         const HCfavor_e favorDecSpeed)
00254 {
00255     U16* const chainTable = hc4->chainTable;
00256     U32* const HashTable = hc4->hashTable;
00257     const LZ4HC_CCtx_internal * const dictCtx = hc4->dictCtx;
00258     const BYTE* const prefixPtr = hc4->prefixStart;
00259     const U32 prefixIdx = hc4->dictLimit;
00260     const U32 ipIndex = (U32)(ip - prefixPtr) + prefixIdx;
00261     const int withinStartDistance = (hc4->lowLimit + (LZ4_DISTANCE_MAX + 1) > ipIndex);
00262     const U32 lowestMatchIndex = (withinStartDistance) ? hc4->lowLimit : ipIndex - LZ4_DISTANCE_MAX;
00263     const BYTE* const dictStart = hc4->dictStart;
00264     const U32 dictIdx = hc4->lowLimit;
00265     const BYTE* const dictEnd = dictStart + prefixIdx - dictIdx;
00266     int const lookBackLength = (int)(ip-iLowLimit);
00267     int nbAttempts = maxNbAttempts;
00268     U32 matchChainPos = 0;
00269     U32 const pattern = LZ4_read32(ip);
00270     U32 matchIndex;
00271     repeat_state_e repeat = rep_untested;
00272     size_t srcPatternLength = 0;
00273 
00274     DEBUGLOG(7, "LZ4HC_InsertAndGetWiderMatch");
00275     /* First Match */
00276     LZ4HC_Insert(hc4, ip);
00277     matchIndex = HashTable[LZ4HC_hashPtr(ip)];
00278     DEBUGLOG(7, "First match at index %u / %u (lowestMatchIndex)",
00279                 matchIndex, lowestMatchIndex);
00280 
00281     while ((matchIndex>=lowestMatchIndex) && (nbAttempts>0)) {
00282         int matchLength=0;
00283         nbAttempts--;
00284         assert(matchIndex < ipIndex);
00285         if (favorDecSpeed && (ipIndex - matchIndex < 8)) {
00286             /* do nothing */
00287         } else if (matchIndex >= prefixIdx) {   /* within current Prefix */
00288             const BYTE* const matchPtr = prefixPtr + matchIndex - prefixIdx;
00289             assert(matchPtr < ip);
00290             assert(longest >= 1);
00291             if (LZ4_read16(iLowLimit + longest - 1) == LZ4_read16(matchPtr - lookBackLength + longest - 1)) {
00292                 if (LZ4_read32(matchPtr) == pattern) {
00293                     int const back = lookBackLength ? LZ4HC_countBack(ip, matchPtr, iLowLimit, prefixPtr) : 0;
00294                     matchLength = MINMATCH + (int)LZ4_count(ip+MINMATCH, matchPtr+MINMATCH, iHighLimit);
00295                     matchLength -= back;
00296                     if (matchLength > longest) {
00297                         longest = matchLength;
00298                         *matchpos = matchPtr + back;
00299                         *startpos = ip + back;
00300             }   }   }
00301         } else {   /* lowestMatchIndex <= matchIndex < dictLimit */
00302             const BYTE* const matchPtr = dictStart + (matchIndex - dictIdx);
00303             assert(matchIndex >= dictIdx);
00304             if ( likely(matchIndex <= prefixIdx - 4)
00305               && (LZ4_read32(matchPtr) == pattern) ) {
00306                 int back = 0;
00307                 const BYTE* vLimit = ip + (prefixIdx - matchIndex);
00308                 if (vLimit > iHighLimit) vLimit = iHighLimit;
00309                 matchLength = (int)LZ4_count(ip+MINMATCH, matchPtr+MINMATCH, vLimit) + MINMATCH;
00310                 if ((ip+matchLength == vLimit) && (vLimit < iHighLimit))
00311                     matchLength += LZ4_count(ip+matchLength, prefixPtr, iHighLimit);
00312                 back = lookBackLength ? LZ4HC_countBack(ip, matchPtr, iLowLimit, dictStart) : 0;
00313                 matchLength -= back;
00314                 if (matchLength > longest) {
00315                     longest = matchLength;
00316                     *matchpos = prefixPtr - prefixIdx + matchIndex + back;   /* virtual pos, relative to ip, to retrieve offset */
00317                     *startpos = ip + back;
00318         }   }   }
00319 
00320         if (chainSwap && matchLength==longest) {   /* better match => select a better chain */
00321             assert(lookBackLength==0);   /* search forward only */
00322             if (matchIndex + (U32)longest <= ipIndex) {
00323                 int const kTrigger = 4;
00324                 U32 distanceToNextMatch = 1;
00325                 int const end = longest - MINMATCH + 1;
00326                 int step = 1;
00327                 int accel = 1 << kTrigger;
00328                 int pos;
00329                 for (pos = 0; pos < end; pos += step) {
00330                     U32 const candidateDist = DELTANEXTU16(chainTable, matchIndex + (U32)pos);
00331                     step = (accel++ >> kTrigger);
00332                     if (candidateDist > distanceToNextMatch) {
00333                         distanceToNextMatch = candidateDist;
00334                         matchChainPos = (U32)pos;
00335                         accel = 1 << kTrigger;
00336                 }   }
00337                 if (distanceToNextMatch > 1) {
00338                     if (distanceToNextMatch > matchIndex) break;   /* avoid overflow */
00339                     matchIndex -= distanceToNextMatch;
00340                     continue;
00341         }   }   }
00342 
00343         {   U32 const distNextMatch = DELTANEXTU16(chainTable, matchIndex);
00344             if (patternAnalysis && distNextMatch==1 && matchChainPos==0) {
00345                 U32 const matchCandidateIdx = matchIndex-1;
00346                 /* may be a repeated pattern */
00347                 if (repeat == rep_untested) {
00348                     if ( ((pattern & 0xFFFF) == (pattern >> 16))
00349                       &  ((pattern & 0xFF)   == (pattern >> 24)) ) {
00350                         repeat = rep_confirmed;
00351                         srcPatternLength = LZ4HC_countPattern(ip+sizeof(pattern), iHighLimit, pattern) + sizeof(pattern);
00352                     } else {
00353                         repeat = rep_not;
00354                 }   }
00355                 if ( (repeat == rep_confirmed) && (matchCandidateIdx >= lowestMatchIndex)
00356                   && LZ4HC_protectDictEnd(prefixIdx, matchCandidateIdx) ) {
00357                     const int extDict = matchCandidateIdx < prefixIdx;
00358                     const BYTE* const matchPtr = (extDict ? dictStart - dictIdx : prefixPtr - prefixIdx) + matchCandidateIdx;
00359                     if (LZ4_read32(matchPtr) == pattern) {  /* good candidate */
00360                         const BYTE* const iLimit = extDict ? dictEnd : iHighLimit;
00361                         size_t forwardPatternLength = LZ4HC_countPattern(matchPtr+sizeof(pattern), iLimit, pattern) + sizeof(pattern);
00362                         if (extDict && matchPtr + forwardPatternLength == iLimit) {
00363                             U32 const rotatedPattern = LZ4HC_rotatePattern(forwardPatternLength, pattern);
00364                             forwardPatternLength += LZ4HC_countPattern(prefixPtr, iHighLimit, rotatedPattern);
00365                         }
00366                         {   const BYTE* const lowestMatchPtr = extDict ? dictStart : prefixPtr;
00367                             size_t backLength = LZ4HC_reverseCountPattern(matchPtr, lowestMatchPtr, pattern);
00368                             size_t currentSegmentLength;
00369                             if (!extDict
00370                               && matchPtr - backLength == prefixPtr
00371                               && dictIdx < prefixIdx) {
00372                                 U32 const rotatedPattern = LZ4HC_rotatePattern((U32)(-(int)backLength), pattern);
00373                                 backLength += LZ4HC_reverseCountPattern(dictEnd, dictStart, rotatedPattern);
00374                             }
00375                             /* Limit backLength not go further than lowestMatchIndex */
00376                             backLength = matchCandidateIdx - MAX(matchCandidateIdx - (U32)backLength, lowestMatchIndex);
00377                             assert(matchCandidateIdx - backLength >= lowestMatchIndex);
00378                             currentSegmentLength = backLength + forwardPatternLength;
00379                             /* Adjust to end of pattern if the source pattern fits, otherwise the beginning of the pattern */
00380                             if ( (currentSegmentLength >= srcPatternLength)   /* current pattern segment large enough to contain full srcPatternLength */
00381                               && (forwardPatternLength <= srcPatternLength) ) { /* haven't reached this position yet */
00382                                 U32 const newMatchIndex = matchCandidateIdx + (U32)forwardPatternLength - (U32)srcPatternLength;  /* best position, full pattern, might be followed by more match */
00383                                 if (LZ4HC_protectDictEnd(prefixIdx, newMatchIndex))
00384                                     matchIndex = newMatchIndex;
00385                                 else {
00386                                     /* Can only happen if started in the prefix */
00387                                     assert(newMatchIndex >= prefixIdx - 3 && newMatchIndex < prefixIdx && !extDict);
00388                                     matchIndex = prefixIdx;
00389                                 }
00390                             } else {
00391                                 U32 const newMatchIndex = matchCandidateIdx - (U32)backLength;   /* farthest position in current segment, will find a match of length currentSegmentLength + maybe some back */
00392                                 if (!LZ4HC_protectDictEnd(prefixIdx, newMatchIndex)) {
00393                                     assert(newMatchIndex >= prefixIdx - 3 && newMatchIndex < prefixIdx && !extDict);
00394                                     matchIndex = prefixIdx;
00395                                 } else {
00396                                     matchIndex = newMatchIndex;
00397                                     if (lookBackLength==0) {  /* no back possible */
00398                                         size_t const maxML = MIN(currentSegmentLength, srcPatternLength);
00399                                         if ((size_t)longest < maxML) {
00400                                             assert(prefixPtr - prefixIdx + matchIndex != ip);
00401                                             if ((size_t)(ip - prefixPtr) + prefixIdx - matchIndex > LZ4_DISTANCE_MAX) break;
00402                                             assert(maxML < 2 GB);
00403                                             longest = (int)maxML;
00404                                             *matchpos = prefixPtr - prefixIdx + matchIndex;   /* virtual pos, relative to ip, to retrieve offset */
00405                                             *startpos = ip;
00406                                         }
00407                                         {   U32 const distToNextPattern = DELTANEXTU16(chainTable, matchIndex);
00408                                             if (distToNextPattern > matchIndex) break;  /* avoid overflow */
00409                                             matchIndex -= distToNextPattern;
00410                         }   }   }   }   }
00411                         continue;
00412                 }   }
00413         }   }   /* PA optimization */
00414 
00415         /* follow current chain */
00416         matchIndex -= DELTANEXTU16(chainTable, matchIndex + matchChainPos);
00417 
00418     }  /* while ((matchIndex>=lowestMatchIndex) && (nbAttempts)) */
00419 
00420     if ( dict == usingDictCtxHc
00421       && nbAttempts > 0
00422       && ipIndex - lowestMatchIndex < LZ4_DISTANCE_MAX) {
00423         size_t const dictEndOffset = (size_t)(dictCtx->end - dictCtx->prefixStart) + dictCtx->dictLimit;
00424         U32 dictMatchIndex = dictCtx->hashTable[LZ4HC_hashPtr(ip)];
00425         assert(dictEndOffset <= 1 GB);
00426         matchIndex = dictMatchIndex + lowestMatchIndex - (U32)dictEndOffset;
00427         while (ipIndex - matchIndex <= LZ4_DISTANCE_MAX && nbAttempts--) {
00428             const BYTE* const matchPtr = dictCtx->prefixStart - dictCtx->dictLimit + dictMatchIndex;
00429 
00430             if (LZ4_read32(matchPtr) == pattern) {
00431                 int mlt;
00432                 int back = 0;
00433                 const BYTE* vLimit = ip + (dictEndOffset - dictMatchIndex);
00434                 if (vLimit > iHighLimit) vLimit = iHighLimit;
00435                 mlt = (int)LZ4_count(ip+MINMATCH, matchPtr+MINMATCH, vLimit) + MINMATCH;
00436                 back = lookBackLength ? LZ4HC_countBack(ip, matchPtr, iLowLimit, dictCtx->prefixStart) : 0;
00437                 mlt -= back;
00438                 if (mlt > longest) {
00439                     longest = mlt;
00440                     *matchpos = prefixPtr - prefixIdx + matchIndex + back;
00441                     *startpos = ip + back;
00442             }   }
00443 
00444             {   U32 const nextOffset = DELTANEXTU16(dictCtx->chainTable, dictMatchIndex);
00445                 dictMatchIndex -= nextOffset;
00446                 matchIndex -= nextOffset;
00447     }   }   }
00448 
00449     return longest;
00450 }
00451 
00452 LZ4_FORCE_INLINE int
00453 LZ4HC_InsertAndFindBestMatch(LZ4HC_CCtx_internal* const hc4,   /* Index table will be updated */
00454                        const BYTE* const ip, const BYTE* const iLimit,
00455                        const BYTE** matchpos,
00456                        const int maxNbAttempts,
00457                        const int patternAnalysis,
00458                        const dictCtx_directive dict)
00459 {
00460     const BYTE* uselessPtr = ip;
00461     /* note : LZ4HC_InsertAndGetWiderMatch() is able to modify the starting position of a match (*startpos),
00462      * but this won't be the case here, as we define iLowLimit==ip,
00463      * so LZ4HC_InsertAndGetWiderMatch() won't be allowed to search past ip */
00464     return LZ4HC_InsertAndGetWiderMatch(hc4, ip, ip, iLimit, MINMATCH-1, matchpos, &uselessPtr, maxNbAttempts, patternAnalysis, 0 /*chainSwap*/, dict, favorCompressionRatio);
00465 }
00466 
00467 /* LZ4HC_encodeSequence() :
00468  * @return : 0 if ok,
00469  *           1 if buffer issue detected */
00470 LZ4_FORCE_INLINE int LZ4HC_encodeSequence (
00471     const BYTE** _ip,
00472     BYTE** _op,
00473     const BYTE** _anchor,
00474     int matchLength,
00475     const BYTE* const match,
00476     limitedOutput_directive limit,
00477     BYTE* oend)
00478 {
00479 #define ip      (*_ip)
00480 #define op      (*_op)
00481 #define anchor  (*_anchor)
00482 
00483     size_t length;
00484     BYTE* const token = op++;
00485 
00486 #if defined(LZ4_DEBUG) && (LZ4_DEBUG >= 6)
00487     static const BYTE* start = NULL;
00488     static U32 totalCost = 0;
00489     U32 const pos = (start==NULL) ? 0 : (U32)(anchor - start);
00490     U32 const ll = (U32)(ip - anchor);
00491     U32 const llAdd = (ll>=15) ? ((ll-15) / 255) + 1 : 0;
00492     U32 const mlAdd = (matchLength>=19) ? ((matchLength-19) / 255) + 1 : 0;
00493     U32 const cost = 1 + llAdd + ll + 2 + mlAdd;
00494     if (start==NULL) start = anchor;  /* only works for single segment */
00495     /* g_debuglog_enable = (pos >= 2228) & (pos <= 2262); */
00496     DEBUGLOG(6, "pos:%7u -- literals:%4u, match:%4i, offset:%5u, cost:%4u + %5u",
00497                 pos,
00498                 (U32)(ip - anchor), matchLength, (U32)(ip-match),
00499                 cost, totalCost);
00500     totalCost += cost;
00501 #endif
00502 
00503     /* Encode Literal length */
00504     length = (size_t)(ip - anchor);
00505     LZ4_STATIC_ASSERT(notLimited == 0);
00506     /* Check output limit */
00507     if (limit && ((op + (length / 255) + length + (2 + 1 + LASTLITERALS)) > oend)) {
00508         DEBUGLOG(6, "Not enough room to write %i literals (%i bytes remaining)",
00509                 (int)length, (int)(oend - op));
00510         return 1;
00511     }
00512     if (length >= RUN_MASK) {
00513         size_t len = length - RUN_MASK;
00514         *token = (RUN_MASK << ML_BITS);
00515         for(; len >= 255 ; len -= 255) *op++ = 255;
00516         *op++ = (BYTE)len;
00517     } else {
00518         *token = (BYTE)(length << ML_BITS);
00519     }
00520 
00521     /* Copy Literals */
00522     LZ4_wildCopy8(op, anchor, op + length);
00523     op += length;
00524 
00525     /* Encode Offset */
00526     assert( (ip - match) <= LZ4_DISTANCE_MAX );   /* note : consider providing offset as a value, rather than as a pointer difference */
00527     LZ4_writeLE16(op, (U16)(ip - match)); op += 2;
00528 
00529     /* Encode MatchLength */
00530     assert(matchLength >= MINMATCH);
00531     length = (size_t)matchLength - MINMATCH;
00532     if (limit && (op + (length / 255) + (1 + LASTLITERALS) > oend)) {
00533         DEBUGLOG(6, "Not enough room to write match length");
00534         return 1;   /* Check output limit */
00535     }
00536     if (length >= ML_MASK) {
00537         *token += ML_MASK;
00538         length -= ML_MASK;
00539         for(; length >= 510 ; length -= 510) { *op++ = 255; *op++ = 255; }
00540         if (length >= 255) { length -= 255; *op++ = 255; }
00541         *op++ = (BYTE)length;
00542     } else {
00543         *token += (BYTE)(length);
00544     }
00545 
00546     /* Prepare next loop */
00547     ip += matchLength;
00548     anchor = ip;
00549 
00550     return 0;
00551 }
00552 #undef ip
00553 #undef op
00554 #undef anchor
00555 
00556 LZ4_FORCE_INLINE int LZ4HC_compress_hashChain (
00557     LZ4HC_CCtx_internal* const ctx,
00558     const char* const source,
00559     char* const dest,
00560     int* srcSizePtr,
00561     int const maxOutputSize,
00562     int maxNbAttempts,
00563     const limitedOutput_directive limit,
00564     const dictCtx_directive dict
00565     )
00566 {
00567     const int inputSize = *srcSizePtr;
00568     const int patternAnalysis = (maxNbAttempts > 128);   /* levels 9+ */
00569 
00570     const BYTE* ip = (const BYTE*) source;
00571     const BYTE* anchor = ip;
00572     const BYTE* const iend = ip + inputSize;
00573     const BYTE* const mflimit = iend - MFLIMIT;
00574     const BYTE* const matchlimit = (iend - LASTLITERALS);
00575 
00576     BYTE* optr = (BYTE*) dest;
00577     BYTE* op = (BYTE*) dest;
00578     BYTE* oend = op + maxOutputSize;
00579 
00580     int   ml0, ml, ml2, ml3;
00581     const BYTE* start0;
00582     const BYTE* ref0;
00583     const BYTE* ref = NULL;
00584     const BYTE* start2 = NULL;
00585     const BYTE* ref2 = NULL;
00586     const BYTE* start3 = NULL;
00587     const BYTE* ref3 = NULL;
00588 
00589     /* init */
00590     *srcSizePtr = 0;
00591     if (limit == fillOutput) oend -= LASTLITERALS;                  /* Hack for support LZ4 format restriction */
00592     if (inputSize < LZ4_minLength) goto _last_literals;             /* Input too small, no compression (all literals) */
00593 
00594     /* Main Loop */
00595     while (ip <= mflimit) {
00596         ml = LZ4HC_InsertAndFindBestMatch(ctx, ip, matchlimit, &ref, maxNbAttempts, patternAnalysis, dict);
00597         if (ml<MINMATCH) { ip++; continue; }
00598 
00599         /* saved, in case we would skip too much */
00600         start0 = ip; ref0 = ref; ml0 = ml;
00601 
00602 _Search2:
00603         if (ip+ml <= mflimit) {
00604             ml2 = LZ4HC_InsertAndGetWiderMatch(ctx,
00605                             ip + ml - 2, ip + 0, matchlimit, ml, &ref2, &start2,
00606                             maxNbAttempts, patternAnalysis, 0, dict, favorCompressionRatio);
00607         } else {
00608             ml2 = ml;
00609         }
00610 
00611         if (ml2 == ml) { /* No better match => encode ML1 */
00612             optr = op;
00613             if (LZ4HC_encodeSequence(UPDATABLE(ip, op, anchor), ml, ref, limit, oend)) goto _dest_overflow;
00614             continue;
00615         }
00616 
00617         if (start0 < ip) {   /* first match was skipped at least once */
00618             if (start2 < ip + ml0) {  /* squeezing ML1 between ML0(original ML1) and ML2 */
00619                 ip = start0; ref = ref0; ml = ml0;  /* restore initial ML1 */
00620         }   }
00621 
00622         /* Here, start0==ip */
00623         if ((start2 - ip) < 3) {  /* First Match too small : removed */
00624             ml = ml2;
00625             ip = start2;
00626             ref =ref2;
00627             goto _Search2;
00628         }
00629 
00630 _Search3:
00631         /* At this stage, we have :
00632         *  ml2 > ml1, and
00633         *  ip1+3 <= ip2 (usually < ip1+ml1) */
00634         if ((start2 - ip) < OPTIMAL_ML) {
00635             int correction;
00636             int new_ml = ml;
00637             if (new_ml > OPTIMAL_ML) new_ml = OPTIMAL_ML;
00638             if (ip+new_ml > start2 + ml2 - MINMATCH) new_ml = (int)(start2 - ip) + ml2 - MINMATCH;
00639             correction = new_ml - (int)(start2 - ip);
00640             if (correction > 0) {
00641                 start2 += correction;
00642                 ref2 += correction;
00643                 ml2 -= correction;
00644             }
00645         }
00646         /* Now, we have start2 = ip+new_ml, with new_ml = min(ml, OPTIMAL_ML=18) */
00647 
00648         if (start2 + ml2 <= mflimit) {
00649             ml3 = LZ4HC_InsertAndGetWiderMatch(ctx,
00650                             start2 + ml2 - 3, start2, matchlimit, ml2, &ref3, &start3,
00651                             maxNbAttempts, patternAnalysis, 0, dict, favorCompressionRatio);
00652         } else {
00653             ml3 = ml2;
00654         }
00655 
00656         if (ml3 == ml2) {  /* No better match => encode ML1 and ML2 */
00657             /* ip & ref are known; Now for ml */
00658             if (start2 < ip+ml)  ml = (int)(start2 - ip);
00659             /* Now, encode 2 sequences */
00660             optr = op;
00661             if (LZ4HC_encodeSequence(UPDATABLE(ip, op, anchor), ml, ref, limit, oend)) goto _dest_overflow;
00662             ip = start2;
00663             optr = op;
00664             if (LZ4HC_encodeSequence(UPDATABLE(ip, op, anchor), ml2, ref2, limit, oend)) {
00665                 ml  = ml2;
00666                 ref = ref2;
00667                 goto _dest_overflow;
00668             }
00669             continue;
00670         }
00671 
00672         if (start3 < ip+ml+3) {  /* Not enough space for match 2 : remove it */
00673             if (start3 >= (ip+ml)) {  /* can write Seq1 immediately ==> Seq2 is removed, so Seq3 becomes Seq1 */
00674                 if (start2 < ip+ml) {
00675                     int correction = (int)(ip+ml - start2);
00676                     start2 += correction;
00677                     ref2 += correction;
00678                     ml2 -= correction;
00679                     if (ml2 < MINMATCH) {
00680                         start2 = start3;
00681                         ref2 = ref3;
00682                         ml2 = ml3;
00683                     }
00684                 }
00685 
00686                 optr = op;
00687                 if (LZ4HC_encodeSequence(UPDATABLE(ip, op, anchor), ml, ref, limit, oend)) goto _dest_overflow;
00688                 ip  = start3;
00689                 ref = ref3;
00690                 ml  = ml3;
00691 
00692                 start0 = start2;
00693                 ref0 = ref2;
00694                 ml0 = ml2;
00695                 goto _Search2;
00696             }
00697 
00698             start2 = start3;
00699             ref2 = ref3;
00700             ml2 = ml3;
00701             goto _Search3;
00702         }
00703 
00704         /*
00705         * OK, now we have 3 ascending matches;
00706         * let's write the first one ML1.
00707         * ip & ref are known; Now decide ml.
00708         */
00709         if (start2 < ip+ml) {
00710             if ((start2 - ip) < OPTIMAL_ML) {
00711                 int correction;
00712                 if (ml > OPTIMAL_ML) ml = OPTIMAL_ML;
00713                 if (ip + ml > start2 + ml2 - MINMATCH) ml = (int)(start2 - ip) + ml2 - MINMATCH;
00714                 correction = ml - (int)(start2 - ip);
00715                 if (correction > 0) {
00716                     start2 += correction;
00717                     ref2 += correction;
00718                     ml2 -= correction;
00719                 }
00720             } else {
00721                 ml = (int)(start2 - ip);
00722             }
00723         }
00724         optr = op;
00725         if (LZ4HC_encodeSequence(UPDATABLE(ip, op, anchor), ml, ref, limit, oend)) goto _dest_overflow;
00726 
00727         /* ML2 becomes ML1 */
00728         ip = start2; ref = ref2; ml = ml2;
00729 
00730         /* ML3 becomes ML2 */
00731         start2 = start3; ref2 = ref3; ml2 = ml3;
00732 
00733         /* let's find a new ML3 */
00734         goto _Search3;
00735     }
00736 
00737 _last_literals:
00738     /* Encode Last Literals */
00739     {   size_t lastRunSize = (size_t)(iend - anchor);  /* literals */
00740         size_t llAdd = (lastRunSize + 255 - RUN_MASK) / 255;
00741         size_t const totalSize = 1 + llAdd + lastRunSize;
00742         if (limit == fillOutput) oend += LASTLITERALS;  /* restore correct value */
00743         if (limit && (op + totalSize > oend)) {
00744             if (limit == limitedOutput) return 0;
00745             /* adapt lastRunSize to fill 'dest' */
00746             lastRunSize  = (size_t)(oend - op) - 1 /*token*/;
00747             llAdd = (lastRunSize + 256 - RUN_MASK) / 256;
00748             lastRunSize -= llAdd;
00749         }
00750         DEBUGLOG(6, "Final literal run : %i literals", (int)lastRunSize);
00751         ip = anchor + lastRunSize;  /* can be != iend if limit==fillOutput */
00752 
00753         if (lastRunSize >= RUN_MASK) {
00754             size_t accumulator = lastRunSize - RUN_MASK;
00755             *op++ = (RUN_MASK << ML_BITS);
00756             for(; accumulator >= 255 ; accumulator -= 255) *op++ = 255;
00757             *op++ = (BYTE) accumulator;
00758         } else {
00759             *op++ = (BYTE)(lastRunSize << ML_BITS);
00760         }
00761         LZ4_memcpy(op, anchor, lastRunSize);
00762         op += lastRunSize;
00763     }
00764 
00765     /* End */
00766     *srcSizePtr = (int) (((const char*)ip) - source);
00767     return (int) (((char*)op)-dest);
00768 
00769 _dest_overflow:
00770     if (limit == fillOutput) {
00771         /* Assumption : ip, anchor, ml and ref must be set correctly */
00772         size_t const ll = (size_t)(ip - anchor);
00773         size_t const ll_addbytes = (ll + 240) / 255;
00774         size_t const ll_totalCost = 1 + ll_addbytes + ll;
00775         BYTE* const maxLitPos = oend - 3; /* 2 for offset, 1 for token */
00776         DEBUGLOG(6, "Last sequence overflowing");
00777         op = optr;  /* restore correct out pointer */
00778         if (op + ll_totalCost <= maxLitPos) {
00779             /* ll validated; now adjust match length */
00780             size_t const bytesLeftForMl = (size_t)(maxLitPos - (op+ll_totalCost));
00781             size_t const maxMlSize = MINMATCH + (ML_MASK-1) + (bytesLeftForMl * 255);
00782             assert(maxMlSize < INT_MAX); assert(ml >= 0);
00783             if ((size_t)ml > maxMlSize) ml = (int)maxMlSize;
00784             if ((oend + LASTLITERALS) - (op + ll_totalCost + 2) - 1 + ml >= MFLIMIT) {
00785                 LZ4HC_encodeSequence(UPDATABLE(ip, op, anchor), ml, ref, notLimited, oend);
00786         }   }
00787         goto _last_literals;
00788     }
00789     /* compression failed */
00790     return 0;
00791 }
00792 
00793 
00794 static int LZ4HC_compress_optimal( LZ4HC_CCtx_internal* ctx,
00795     const char* const source, char* dst,
00796     int* srcSizePtr, int dstCapacity,
00797     int const nbSearches, size_t sufficient_len,
00798     const limitedOutput_directive limit, int const fullUpdate,
00799     const dictCtx_directive dict,
00800     const HCfavor_e favorDecSpeed);
00801 
00802 
00803 LZ4_FORCE_INLINE int LZ4HC_compress_generic_internal (
00804     LZ4HC_CCtx_internal* const ctx,
00805     const char* const src,
00806     char* const dst,
00807     int* const srcSizePtr,
00808     int const dstCapacity,
00809     int cLevel,
00810     const limitedOutput_directive limit,
00811     const dictCtx_directive dict
00812     )
00813 {
00814     typedef enum { lz4hc, lz4opt } lz4hc_strat_e;
00815     typedef struct {
00816         lz4hc_strat_e strat;
00817         int nbSearches;
00818         U32 targetLength;
00819     } cParams_t;
00820     static const cParams_t clTable[LZ4HC_CLEVEL_MAX+1] = {
00821         { lz4hc,     2, 16 },  /* 0, unused */
00822         { lz4hc,     2, 16 },  /* 1, unused */
00823         { lz4hc,     2, 16 },  /* 2, unused */
00824         { lz4hc,     4, 16 },  /* 3 */
00825         { lz4hc,     8, 16 },  /* 4 */
00826         { lz4hc,    16, 16 },  /* 5 */
00827         { lz4hc,    32, 16 },  /* 6 */
00828         { lz4hc,    64, 16 },  /* 7 */
00829         { lz4hc,   128, 16 },  /* 8 */
00830         { lz4hc,   256, 16 },  /* 9 */
00831         { lz4opt,   96, 64 },  /*10==LZ4HC_CLEVEL_OPT_MIN*/
00832         { lz4opt,  512,128 },  /*11 */
00833         { lz4opt,16384,LZ4_OPT_NUM },  /* 12==LZ4HC_CLEVEL_MAX */
00834     };
00835 
00836     DEBUGLOG(4, "LZ4HC_compress_generic(ctx=%p, src=%p, srcSize=%d, limit=%d)",
00837                 ctx, src, *srcSizePtr, limit);
00838 
00839     if (limit == fillOutput && dstCapacity < 1) return 0;   /* Impossible to store anything */
00840     if ((U32)*srcSizePtr > (U32)LZ4_MAX_INPUT_SIZE) return 0;    /* Unsupported input size (too large or negative) */
00841 
00842     ctx->end += *srcSizePtr;
00843     if (cLevel < 1) cLevel = LZ4HC_CLEVEL_DEFAULT;   /* note : convention is different from lz4frame, maybe something to review */
00844     cLevel = MIN(LZ4HC_CLEVEL_MAX, cLevel);
00845     {   cParams_t const cParam = clTable[cLevel];
00846         HCfavor_e const favor = ctx->favorDecSpeed ? favorDecompressionSpeed : favorCompressionRatio;
00847         int result;
00848 
00849         if (cParam.strat == lz4hc) {
00850             result = LZ4HC_compress_hashChain(ctx,
00851                                 src, dst, srcSizePtr, dstCapacity,
00852                                 cParam.nbSearches, limit, dict);
00853         } else {
00854             assert(cParam.strat == lz4opt);
00855             result = LZ4HC_compress_optimal(ctx,
00856                                 src, dst, srcSizePtr, dstCapacity,
00857                                 cParam.nbSearches, cParam.targetLength, limit,
00858                                 cLevel == LZ4HC_CLEVEL_MAX,   /* ultra mode */
00859                                 dict, favor);
00860         }
00861         if (result <= 0) ctx->dirty = 1;
00862         return result;
00863     }
00864 }
