00866 static void LZ4HC_setExternalDict(LZ4HC_CCtx_internal* ctxPtr, const BYTE* newBlock);
00867 
00868 static int
00869 LZ4HC_compress_generic_noDictCtx (
00870         LZ4HC_CCtx_internal* const ctx,
00871         const char* const src,
00872         char* const dst,
00873         int* const srcSizePtr,
00874         int const dstCapacity,
00875         int cLevel,
00876         limitedOutput_directive limit
00877         )
00878 {
00879     assert(ctx->dictCtx == NULL);
00880     return LZ4HC_compress_generic_internal(ctx, src, dst, srcSizePtr, dstCapacity, cLevel, limit, noDictCtx);
00881 }
00882 
00883 static int
00884 LZ4HC_compress_generic_dictCtx (
00885         LZ4HC_CCtx_internal* const ctx,
00886         const char* const src,
00887         char* const dst,
00888         int* const srcSizePtr,
00889         int const dstCapacity,
00890         int cLevel,
00891         limitedOutput_directive limit
00892         )
00893 {
00894     const size_t position = (size_t)(ctx->end - ctx->prefixStart) + (ctx->dictLimit - ctx->lowLimit);
00895     assert(ctx->dictCtx != NULL);
00896     if (position >= 64 KB) {
00897         ctx->dictCtx = NULL;
00898         return LZ4HC_compress_generic_noDictCtx(ctx, src, dst, srcSizePtr, dstCapacity, cLevel, limit);
00899     } else if (position == 0 && *srcSizePtr > 4 KB) {
00900         LZ4_memcpy(ctx, ctx->dictCtx, sizeof(LZ4HC_CCtx_internal));
00901         LZ4HC_setExternalDict(ctx, (const BYTE *)src);
00902         ctx->compressionLevel = (short)cLevel;
00903         return LZ4HC_compress_generic_noDictCtx(ctx, src, dst, srcSizePtr, dstCapacity, cLevel, limit);
00904     } else {
00905         return LZ4HC_compress_generic_internal(ctx, src, dst, srcSizePtr, dstCapacity, cLevel, limit, usingDictCtxHc);
00906     }
00907 }
00908 
00909 static int
00910 LZ4HC_compress_generic (
00911         LZ4HC_CCtx_internal* const ctx,
00912         const char* const src,
00913         char* const dst,
00914         int* const srcSizePtr,
00915         int const dstCapacity,
00916         int cLevel,
00917         limitedOutput_directive limit
00918         )
00919 {
00920     if (ctx->dictCtx == NULL) {
00921         return LZ4HC_compress_generic_noDictCtx(ctx, src, dst, srcSizePtr, dstCapacity, cLevel, limit);
00922     } else {
00923         return LZ4HC_compress_generic_dictCtx(ctx, src, dst, srcSizePtr, dstCapacity, cLevel, limit);
00924     }
00925 }
