00930 static size_t LZ4_streamHC_t_alignment(void)
00931 {
00932 #if LZ4_ALIGN_TEST
00933     typedef struct { char c; LZ4_streamHC_t t; } t_a;
00934     return sizeof(t_a) - sizeof(LZ4_streamHC_t);
00935 #else
00936     return 1;  /* effectively disabled */
00937 #endif
