00940 /* state is presumed correctly initialized,
00941  * in which case its size and alignment have already been validate */
00942 int LZ4_compress_HC_extStateHC_fastReset (void* state, const char* src, char* dst, int srcSize, int dstCapacity, int compressionLevel)
00943 {
00944     LZ4HC_CCtx_internal* const ctx = &((LZ4_streamHC_t*)state)->internal_donotuse;
00945     if (!LZ4_isAligned(state, LZ4_streamHC_t_alignment())) return 0;
00946     LZ4_resetStreamHC_fast((LZ4_streamHC_t*)state, compressionLevel);
00947     LZ4HC_init_internal (ctx, (const BYTE*)src);
00948     if (dstCapacity < LZ4_compressBound(srcSize))
00949         return LZ4HC_compress_generic (ctx, src, dst, &srcSize, dstCapacity, compressionLevel, limitedOutput);
00950     else
00951         return LZ4HC_compress_generic (ctx, src, dst, &srcSize, dstCapacity, compressionLevel, notLimited);
00952 }
00953 
00954 int LZ4_compress_HC_extStateHC (void* state, const char* src, char* dst, int srcSize, int dstCapacity, int compressionLevel)
00955 {
00956     LZ4_streamHC_t* const ctx = LZ4_initStreamHC(state, sizeof(*ctx));
00957     if (ctx==NULL) return 0;   /* init failure */
00958     return LZ4_compress_HC_extStateHC_fastReset(state, src, dst, srcSize, dstCapacity, compressionLevel);
00959 }
00960 
00961 int LZ4_compress_HC(const char* src, char* dst, int srcSize, int dstCapacity, int compressionLevel)
00962 {
00963     int cSize;
00964 #if defined(LZ4HC_HEAPMODE) && LZ4HC_HEAPMODE==1
00965     LZ4_streamHC_t* const statePtr = (LZ4_streamHC_t*)ALLOC(sizeof(LZ4_streamHC_t));
00966     if (statePtr==NULL) return 0;
00967 #else
00968     LZ4_streamHC_t state;
00969     LZ4_streamHC_t* const statePtr = &state;
00970 #endif
00971     cSize = LZ4_compress_HC_extStateHC(statePtr, src, dst, srcSize, dstCapacity, compressionLevel);
00972 #if defined(LZ4HC_HEAPMODE) && LZ4HC_HEAPMODE==1
00973     FREEMEM(statePtr);
00974 #endif
00975     return cSize;
00976 }
00977 
00978 /* state is presumed sized correctly (>= sizeof(LZ4_streamHC_t)) */
00979 int LZ4_compress_HC_destSize(void* state, const char* source, char* dest, int* sourceSizePtr, int targetDestSize, int cLevel)
00980 {
00981     LZ4_streamHC_t* const ctx = LZ4_initStreamHC(state, sizeof(*ctx));
00982     if (ctx==NULL) return 0;   /* init failure */
00983     LZ4HC_init_internal(&ctx->internal_donotuse, (const BYTE*) source);
00984     LZ4_setCompressionLevel(ctx, cLevel);
00985     return LZ4HC_compress_generic(&ctx->internal_donotuse, source, dest, sourceSizePtr, targetDestSize, cLevel, fillOutput);
00986 }
