01014 LZ4_streamHC_t* LZ4_initStreamHC (void* buffer, size_t size)
01015 {
01016     LZ4_streamHC_t* const LZ4_streamHCPtr = (LZ4_streamHC_t*)buffer;
01017     DEBUGLOG(4, "LZ4_initStreamHC(%p, %u)", buffer, (unsigned)size);
01018     /* check conditions */
01019     if (buffer == NULL) return NULL;
01020     if (size < sizeof(LZ4_streamHC_t)) return NULL;
01021     if (!LZ4_isAligned(buffer, LZ4_streamHC_t_alignment())) return NULL;
01022     /* init */
01023     { LZ4HC_CCtx_internal* const hcstate = &(LZ4_streamHCPtr->internal_donotuse);
01024       MEM_INIT(hcstate, 0, sizeof(*hcstate)); }
01025     LZ4_setCompressionLevel(LZ4_streamHCPtr, LZ4HC_CLEVEL_DEFAULT);
01026     return LZ4_streamHCPtr;
01027 }
