01035 
01036 void LZ4_resetStreamHC_fast (LZ4_streamHC_t* LZ4_streamHCPtr, int compressionLevel)
01037 {
01038     DEBUGLOG(4, "LZ4_resetStreamHC_fast(%p, %d)", LZ4_streamHCPtr, compressionLevel);
01039     if (LZ4_streamHCPtr->internal_donotuse.dirty) {
01040         LZ4_initStreamHC(LZ4_streamHCPtr, sizeof(*LZ4_streamHCPtr));
01041     } else {
01042         /* preserve end - prefixStart : can trigger clearTable's threshold */
01043         if (LZ4_streamHCPtr->internal_donotuse.end != NULL) {
01044             LZ4_streamHCPtr->internal_donotuse.end -= (uptrval)LZ4_streamHCPtr->internal_donotuse.prefixStart;
01045         } else {
01046             assert(LZ4_streamHCPtr->internal_donotuse.prefixStart == NULL);
01047         }
01048         LZ4_streamHCPtr->internal_donotuse.prefixStart = NULL;
01049         LZ4_streamHCPtr->internal_donotuse.dictCtx = NULL;
01050     }
01051     LZ4_setCompressionLevel(LZ4_streamHCPtr, compressionLevel);
01052 }
01053 
01054 void LZ4_setCompressionLevel(LZ4_streamHC_t* LZ4_streamHCPtr, int compressionLevel)
01055 {
01056     DEBUGLOG(5, "LZ4_setCompressionLevel(%p, %d)", LZ4_streamHCPtr, compressionLevel);
01057     if (compressionLevel < 1) compressionLevel = LZ4HC_CLEVEL_DEFAULT;
01058     if (compressionLevel > LZ4HC_CLEVEL_MAX) compressionLevel = LZ4HC_CLEVEL_MAX;
01059     LZ4_streamHCPtr->internal_donotuse.compressionLevel = (short)compressionLevel;
01060 }
01061 
01062 void LZ4_favorDecompressionSpeed(LZ4_streamHC_t* LZ4_streamHCPtr, int favor)
01063 {
01064     LZ4_streamHCPtr->internal_donotuse.favorDecSpeed = (favor!=0);
01065 }
