01067 /* LZ4_loadDictHC() :
01068  * LZ4_streamHCPtr is presumed properly initialized */
01069 int LZ4_loadDictHC (LZ4_streamHC_t* LZ4_streamHCPtr,
01070               const char* dictionary, int dictSize)
01071 {
01072     LZ4HC_CCtx_internal* const ctxPtr = &LZ4_streamHCPtr->internal_donotuse;
01073     DEBUGLOG(4, "LZ4_loadDictHC(ctx:%p, dict:%p, dictSize:%d)", LZ4_streamHCPtr, dictionary, dictSize);
01074     assert(LZ4_streamHCPtr != NULL);
01075     if (dictSize > 64 KB) {
01076         dictionary += (size_t)dictSize - 64 KB;
01077         dictSize = 64 KB;
01078     }
01079     /* need a full initialization, there are bad side-effects when using resetFast() */
01080     {   int const cLevel = ctxPtr->compressionLevel;
01081         LZ4_initStreamHC(LZ4_streamHCPtr, sizeof(*LZ4_streamHCPtr));
01082         LZ4_setCompressionLevel(LZ4_streamHCPtr, cLevel);
01083     }
01084     LZ4HC_init_internal (ctxPtr, (const BYTE*)dictionary);
01085     ctxPtr->end = (const BYTE*)dictionary + dictSize;
01086     if (dictSize >= 4) LZ4HC_Insert (ctxPtr, ctxPtr->end-3);
01087     return dictSize;
01088 }
