01090 void LZ4_attach_HC_dictionary(LZ4_streamHC_t *working_stream, const LZ4_streamHC_t *dictionary_stream) {
01091     working_stream->internal_donotuse.dictCtx = dictionary_stream != NULL ? &(dictionary_stream->internal_donotuse) : NULL;
01092 }
01093 
01094 /* compression */
01095 
01096 static void LZ4HC_setExternalDict(LZ4HC_CCtx_internal* ctxPtr, const BYTE* newBlock)
01097 {
01098     DEBUGLOG(4, "LZ4HC_setExternalDict(%p, %p)", ctxPtr, newBlock);
01099     if (ctxPtr->end >= ctxPtr->prefixStart + 4)
01100         LZ4HC_Insert (ctxPtr, ctxPtr->end-3);   /* Referencing remaining dictionary content */
01101 
01102     /* Only one memory segment for extDict, so any previous extDict is lost at this stage */
01103     ctxPtr->lowLimit  = ctxPtr->dictLimit;
01104     ctxPtr->dictStart  = ctxPtr->prefixStart;
01105     ctxPtr->dictLimit += (U32)(ctxPtr->end - ctxPtr->prefixStart);
01106     ctxPtr->prefixStart = newBlock;
01107     ctxPtr->end  = newBlock;
01108     ctxPtr->nextToUpdate = ctxPtr->dictLimit;   /* match referencing will resume from there */
01109 
01110     /* cannot reference an extDict and a dictCtx at the same time */
01111     ctxPtr->dictCtx = NULL;
01112 }
01113 
01114 static int
01115 LZ4_compressHC_continue_generic (LZ4_streamHC_t* LZ4_streamHCPtr,
01116                                  const char* src, char* dst,
01117                                  int* srcSizePtr, int dstCapacity,
01118                                  limitedOutput_directive limit)
01119 {
01120     LZ4HC_CCtx_internal* const ctxPtr = &LZ4_streamHCPtr->internal_donotuse;
01121     DEBUGLOG(5, "LZ4_compressHC_continue_generic(ctx=%p, src=%p, srcSize=%d, limit=%d)",
01122                 LZ4_streamHCPtr, src, *srcSizePtr, limit);
01123     assert(ctxPtr != NULL);
01124     /* auto-init if forgotten */
01125     if (ctxPtr->prefixStart == NULL) LZ4HC_init_internal (ctxPtr, (const BYTE*) src);
01126 
01127     /* Check overflow */
01128     if ((size_t)(ctxPtr->end - ctxPtr->prefixStart) + ctxPtr->dictLimit > 2 GB) {
01129         size_t dictSize = (size_t)(ctxPtr->end - ctxPtr->prefixStart);
01130         if (dictSize > 64 KB) dictSize = 64 KB;
01131         LZ4_loadDictHC(LZ4_streamHCPtr, (const char*)(ctxPtr->end) - dictSize, (int)dictSize);
01132     }
01133 
01134     /* Check if blocks follow each other */
01135     if ((const BYTE*)src != ctxPtr->end)
01136         LZ4HC_setExternalDict(ctxPtr, (const BYTE*)src);
01137 
01138     /* Check overlapping input/dictionary space */
01139     {   const BYTE* sourceEnd = (const BYTE*) src + *srcSizePtr;
01140         const BYTE* const dictBegin = ctxPtr->dictStart;
01141         const BYTE* const dictEnd   = ctxPtr->dictStart + (ctxPtr->dictLimit - ctxPtr->lowLimit);
01142         if ((sourceEnd > dictBegin) && ((const BYTE*)src < dictEnd)) {
01143             if (sourceEnd > dictEnd) sourceEnd = dictEnd;
01144             ctxPtr->lowLimit += (U32)(sourceEnd - ctxPtr->dictStart);
01145             ctxPtr->dictStart += (U32)(sourceEnd - ctxPtr->dictStart);
01146             if (ctxPtr->dictLimit - ctxPtr->lowLimit < 4) {
01147                 ctxPtr->lowLimit = ctxPtr->dictLimit;
01148                 ctxPtr->dictStart = ctxPtr->prefixStart;
01149     }   }   }
01150 
01151     return LZ4HC_compress_generic (ctxPtr, src, dst, srcSizePtr, dstCapacity, ctxPtr->compressionLevel, limit);
01152 }
01153 
01154 int LZ4_compress_HC_continue (LZ4_streamHC_t* LZ4_streamHCPtr, const char* src, char* dst, int srcSize, int dstCapacity)
01155 {
01156     if (dstCapacity < LZ4_compressBound(srcSize))
01157         return LZ4_compressHC_continue_generic (LZ4_streamHCPtr, src, dst, &srcSize, dstCapacity, limitedOutput);
01158     else
01159         return LZ4_compressHC_continue_generic (LZ4_streamHCPtr, src, dst, &srcSize, dstCapacity, notLimited);
01160 }
01161 
01162 int LZ4_compress_HC_continue_destSize (LZ4_streamHC_t* LZ4_streamHCPtr, const char* src, char* dst, int* srcSizePtr, int targetDestSize)
01163 {
01164     return LZ4_compressHC_continue_generic(LZ4_streamHCPtr, src, dst, srcSizePtr, targetDestSize, fillOutput);
01165 }
