01169 /* LZ4_saveDictHC :
01170  * save history content
01171  * into a user-provided buffer
01172  * which is then used to continue compression
01173  */
01174 int LZ4_saveDictHC (LZ4_streamHC_t* LZ4_streamHCPtr, char* safeBuffer, int dictSize)
01175 {
01176     LZ4HC_CCtx_internal* const streamPtr = &LZ4_streamHCPtr->internal_donotuse;
01177     int const prefixSize = (int)(streamPtr->end - streamPtr->prefixStart);
01178     DEBUGLOG(5, "LZ4_saveDictHC(%p, %p, %d)", LZ4_streamHCPtr, safeBuffer, dictSize);
01179     assert(prefixSize >= 0);
01180     if (dictSize > 64 KB) dictSize = 64 KB;
01181     if (dictSize < 4) dictSize = 0;
01182     if (dictSize > prefixSize) dictSize = prefixSize;
01183     if (safeBuffer == NULL) assert(dictSize == 0);
01184     if (dictSize > 0)
01185         LZ4_memmove(safeBuffer, streamPtr->end - dictSize, dictSize);
01186     {   U32 const endIndex = (U32)(streamPtr->end - streamPtr->prefixStart) + streamPtr->dictLimit;
01187         streamPtr->end = (const BYTE*)safeBuffer + dictSize;
01188         streamPtr->prefixStart = streamPtr->end - dictSize;
01189         streamPtr->dictLimit = endIndex - (U32)dictSize;
01190         streamPtr->lowLimit = endIndex - (U32)dictSize;
01191         streamPtr->dictStart = streamPtr->prefixStart;
01192         if (streamPtr->nextToUpdate < streamPtr->dictLimit)
01193             streamPtr->nextToUpdate = streamPtr->dictLimit;
01194     }
01195     return dictSize;
01196 }
