01268 /* ================================================
01269  *  LZ4 Optimal parser (levels [LZ4HC_CLEVEL_OPT_MIN - LZ4HC_CLEVEL_MAX])
01270  * ===============================================*/
01271 typedef struct {
01272     int price;
01273     int off;
01274     int mlen;
01275     int litlen;
01276 } LZ4HC_optimal_t;
01277 
01278 /* price in bytes */
01279 LZ4_FORCE_INLINE int LZ4HC_literalsPrice(int const litlen)
01280 {
01281     int price = litlen;
01282     assert(litlen >= 0);
01283     if (litlen >= (int)RUN_MASK)
01284         price += 1 + ((litlen-(int)RUN_MASK) / 255);
01285     return price;
01286 }
01287 
01288 
01289 /* requires mlen >= MINMATCH */
01290 LZ4_FORCE_INLINE int LZ4HC_sequencePrice(int litlen, int mlen)
01291 {
01292     int price = 1 + 2 ; /* token + 16-bit offset */
01293     assert(litlen >= 0);
01294     assert(mlen >= MINMATCH);
01295 
01296     price += LZ4HC_literalsPrice(litlen);
01297 
01298     if (mlen >= (int)(ML_MASK+MINMATCH))
01299         price += 1 + ((mlen-(int)(ML_MASK+MINMATCH)) / 255);
01300 
01301     return price;
01302 }
01303 
01304 
01305 typedef struct {
01306     int off;
01307     int len;
01308 } LZ4HC_match_t;
01309 
01310 LZ4_FORCE_INLINE LZ4HC_match_t
01311 LZ4HC_FindLongerMatch(LZ4HC_CCtx_internal* const ctx,
01312                       const BYTE* ip, const BYTE* const iHighLimit,
01313                       int minLen, int nbSearches,
01314                       const dictCtx_directive dict,
01315                       const HCfavor_e favorDecSpeed)
01316 {
01317     LZ4HC_match_t match = { 0 , 0 };
01318     const BYTE* matchPtr = NULL;
01319     /* note : LZ4HC_InsertAndGetWiderMatch() is able to modify the starting position of a match (*startpos),
01320      * but this won't be the case here, as we define iLowLimit==ip,
01321      * so LZ4HC_InsertAndGetWiderMatch() won't be allowed to search past ip */
01322     int matchLength = LZ4HC_InsertAndGetWiderMatch(ctx, ip, ip, iHighLimit, minLen, &matchPtr, &ip, nbSearches, 1 /*patternAnalysis*/, 1 /*chainSwap*/, dict, favorDecSpeed);
01323     if (matchLength <= minLen) return match;
01324     if (favorDecSpeed) {
01325         if ((matchLength>18) & (matchLength<=36)) matchLength=18;   /* favor shortcut */
01326     }
01327     match.len = matchLength;
01328     match.off = (int)(ip-matchPtr);
01329     return match;
01330 }
01331 
01332 
01333 static int LZ4HC_compress_optimal ( LZ4HC_CCtx_internal* ctx,
01334                                     const char* const source,
01335                                     char* dst,
01336                                     int* srcSizePtr,
01337                                     int dstCapacity,
01338                                     int const nbSearches,
01339                                     size_t sufficient_len,
01340                                     const limitedOutput_directive limit,
01341                                     int const fullUpdate,
01342                                     const dictCtx_directive dict,
01343                                     const HCfavor_e favorDecSpeed)
01344 {
01345     int retval = 0;
01346 #define TRAILING_LITERALS 3
01347 #if defined(LZ4HC_HEAPMODE) && LZ4HC_HEAPMODE==1
01348     LZ4HC_optimal_t* const opt = (LZ4HC_optimal_t*)ALLOC(sizeof(LZ4HC_optimal_t) * (LZ4_OPT_NUM + TRAILING_LITERALS));
01349 #else
01350     LZ4HC_optimal_t opt[LZ4_OPT_NUM + TRAILING_LITERALS];   /* ~64 KB, which is a bit large for stack... */
01351 #endif
01352 
01353     const BYTE* ip = (const BYTE*) source;
01354     const BYTE* anchor = ip;
01355     const BYTE* const iend = ip + *srcSizePtr;
01356     const BYTE* const mflimit = iend - MFLIMIT;
01357     const BYTE* const matchlimit = iend - LASTLITERALS;
01358     BYTE* op = (BYTE*) dst;
01359     BYTE* opSaved = (BYTE*) dst;
01360     BYTE* oend = op + dstCapacity;
01361     int ovml = MINMATCH;  /* overflow - last sequence */
01362     const BYTE* ovref = NULL;
01363 
01364     /* init */
01365 #if defined(LZ4HC_HEAPMODE) && LZ4HC_HEAPMODE==1
01366     if (opt == NULL) goto _return_label;
01367 #endif
01368     DEBUGLOG(5, "LZ4HC_compress_optimal(dst=%p, dstCapa=%u)", dst, (unsigned)dstCapacity);
01369     *srcSizePtr = 0;
01370     if (limit == fillOutput) oend -= LASTLITERALS;   /* Hack for support LZ4 format restriction */
01371     if (sufficient_len >= LZ4_OPT_NUM) sufficient_len = LZ4_OPT_NUM-1;
01372 
01373     /* Main Loop */
01374     while (ip <= mflimit) {
01375          int const llen = (int)(ip - anchor);
01376          int best_mlen, best_off;
01377          int cur, last_match_pos = 0;
01378 
01379          LZ4HC_match_t const firstMatch = LZ4HC_FindLongerMatch(ctx, ip, matchlimit, MINMATCH-1, nbSearches, dict, favorDecSpeed);
01380          if (firstMatch.len==0) { ip++; continue; }
01381 
01382          if ((size_t)firstMatch.len > sufficient_len) {
01383              /* good enough solution : immediate encoding */
01384              int const firstML = firstMatch.len;
01385              const BYTE* const matchPos = ip - firstMatch.off;
01386              opSaved = op;
01387              if ( LZ4HC_encodeSequence(UPDATABLE(ip, op, anchor), firstML, matchPos, limit, oend) ) {  /* updates ip, op and anchor */
01388                  ovml = firstML;
01389                  ovref = matchPos;
01390                  goto _dest_overflow;
01391              }
01392              continue;
01393          }
01394 
01395          /* set prices for first positions (literals) */
01396          {   int rPos;
01397              for (rPos = 0 ; rPos < MINMATCH ; rPos++) {
01398                  int const cost = LZ4HC_literalsPrice(llen + rPos);
01399                  opt[rPos].mlen = 1;
01400                  opt[rPos].off = 0;
01401                  opt[rPos].litlen = llen + rPos;
01402                  opt[rPos].price = cost;
01403                  DEBUGLOG(7, "rPos:%3i => price:%3i (litlen=%i) -- initial setup",
01404                              rPos, cost, opt[rPos].litlen);
01405          }   }
01406          /* set prices using initial match */
01407          {   int mlen = MINMATCH;
01408              int const matchML = firstMatch.len;   /* necessarily < sufficient_len < LZ4_OPT_NUM */
01409              int const offset = firstMatch.off;
01410              assert(matchML < LZ4_OPT_NUM);
01411              for ( ; mlen <= matchML ; mlen++) {
01412                  int const cost = LZ4HC_sequencePrice(llen, mlen);
01413                  opt[mlen].mlen = mlen;
01414                  opt[mlen].off = offset;
01415                  opt[mlen].litlen = llen;
01416                  opt[mlen].price = cost;
01417                  DEBUGLOG(7, "rPos:%3i => price:%3i (matchlen=%i) -- initial setup",
01418                              mlen, cost, mlen);
01419          }   }
01420          last_match_pos = firstMatch.len;
01421          {   int addLit;
01422              for (addLit = 1; addLit <= TRAILING_LITERALS; addLit ++) {
01423                  opt[last_match_pos+addLit].mlen = 1; /* literal */
01424                  opt[last_match_pos+addLit].off = 0;
01425                  opt[last_match_pos+addLit].litlen = addLit;
01426                  opt[last_match_pos+addLit].price = opt[last_match_pos].price + LZ4HC_literalsPrice(addLit);
01427                  DEBUGLOG(7, "rPos:%3i => price:%3i (litlen=%i) -- initial setup",
01428                              last_match_pos+addLit, opt[last_match_pos+addLit].price, addLit);
01429          }   }
01430 
01431          /* check further positions */
01432          for (cur = 1; cur < last_match_pos; cur++) {
01433              const BYTE* const curPtr = ip + cur;
01434              LZ4HC_match_t newMatch;
01435 
01436              if (curPtr > mflimit) break;
01437              DEBUGLOG(7, "rPos:%u[%u] vs [%u]%u",
01438                      cur, opt[cur].price, opt[cur+1].price, cur+1);
01439              if (fullUpdate) {
01440                  /* not useful to search here if next position has same (or lower) cost */
01441                  if ( (opt[cur+1].price <= opt[cur].price)
01442                    /* in some cases, next position has same cost, but cost rises sharply after, so a small match would still be beneficial */
01443                    && (opt[cur+MINMATCH].price < opt[cur].price + 3/*min seq price*/) )
01444                      continue;
01445              } else {
01446                  /* not useful to search here if next position has same (or lower) cost */
01447                  if (opt[cur+1].price <= opt[cur].price) continue;
01448              }
01449 
01450              DEBUGLOG(7, "search at rPos:%u", cur);
01451              if (fullUpdate)
01452                  newMatch = LZ4HC_FindLongerMatch(ctx, curPtr, matchlimit, MINMATCH-1, nbSearches, dict, favorDecSpeed);
01453              else
01454                  /* only test matches of minimum length; slightly faster, but misses a few bytes */
01455                  newMatch = LZ4HC_FindLongerMatch(ctx, curPtr, matchlimit, last_match_pos - cur, nbSearches, dict, favorDecSpeed);
01456              if (!newMatch.len) continue;
01457 
01458              if ( ((size_t)newMatch.len > sufficient_len)
01459                || (newMatch.len + cur >= LZ4_OPT_NUM) ) {
01460                  /* immediate encoding */
01461                  best_mlen = newMatch.len;
01462                  best_off = newMatch.off;
01463                  last_match_pos = cur + 1;
01464                  goto encode;
01465              }
01466 
01467              /* before match : set price with literals at beginning */
01468              {   int const baseLitlen = opt[cur].litlen;
01469                  int litlen;
01470                  for (litlen = 1; litlen < MINMATCH; litlen++) {
01471                      int const price = opt[cur].price - LZ4HC_literalsPrice(baseLitlen) + LZ4HC_literalsPrice(baseLitlen+litlen);
01472                      int const pos = cur + litlen;
01473                      if (price < opt[pos].price) {
01474                          opt[pos].mlen = 1; /* literal */
01475                          opt[pos].off = 0;
01476                          opt[pos].litlen = baseLitlen+litlen;
01477                          opt[pos].price = price;
01478                          DEBUGLOG(7, "rPos:%3i => price:%3i (litlen=%i)",
01479                                      pos, price, opt[pos].litlen);
01480              }   }   }
01481 
01482              /* set prices using match at position = cur */
01483              {   int const matchML = newMatch.len;
01484                  int ml = MINMATCH;
01485 
01486                  assert(cur + newMatch.len < LZ4_OPT_NUM);
01487                  for ( ; ml <= matchML ; ml++) {
01488                      int const pos = cur + ml;
01489                      int const offset = newMatch.off;
01490                      int price;
01491                      int ll;
01492                      DEBUGLOG(7, "testing price rPos %i (last_match_pos=%i)",
01493                                  pos, last_match_pos);
01494                      if (opt[cur].mlen == 1) {
01495                          ll = opt[cur].litlen;
01496                          price = ((cur > ll) ? opt[cur - ll].price : 0)
01497                                + LZ4HC_sequencePrice(ll, ml);
01498                      } else {
01499                          ll = 0;
01500                          price = opt[cur].price + LZ4HC_sequencePrice(0, ml);
01501                      }
01502 
01503                     assert((U32)favorDecSpeed <= 1);
01504                      if (pos > last_match_pos+TRAILING_LITERALS
01505                       || price <= opt[pos].price - (int)favorDecSpeed) {
01506                          DEBUGLOG(7, "rPos:%3i => price:%3i (matchlen=%i)",
01507                                      pos, price, ml);
01508                          assert(pos < LZ4_OPT_NUM);
01509                          if ( (ml == matchML)  /* last pos of last match */
01510                            && (last_match_pos < pos) )
01511                              last_match_pos = pos;
01512                          opt[pos].mlen = ml;
01513                          opt[pos].off = offset;
01514                          opt[pos].litlen = ll;
01515                          opt[pos].price = price;
01516              }   }   }
01517              /* complete following positions with literals */
01518              {   int addLit;
01519                  for (addLit = 1; addLit <= TRAILING_LITERALS; addLit ++) {
01520                      opt[last_match_pos+addLit].mlen = 1; /* literal */
01521                      opt[last_match_pos+addLit].off = 0;
01522                      opt[last_match_pos+addLit].litlen = addLit;
01523                      opt[last_match_pos+addLit].price = opt[last_match_pos].price + LZ4HC_literalsPrice(addLit);
01524                      DEBUGLOG(7, "rPos:%3i => price:%3i (litlen=%i)", last_match_pos+addLit, opt[last_match_pos+addLit].price, addLit);
01525              }   }
01526          }  /* for (cur = 1; cur <= last_match_pos; cur++) */
01527 
01528          assert(last_match_pos < LZ4_OPT_NUM + TRAILING_LITERALS);
01529          best_mlen = opt[last_match_pos].mlen;
01530          best_off = opt[last_match_pos].off;
01531          cur = last_match_pos - best_mlen;
01532 
01533 encode: /* cur, last_match_pos, best_mlen, best_off must be set */
01534          assert(cur < LZ4_OPT_NUM);
01535          assert(last_match_pos >= 1);  /* == 1 when only one candidate */
01536          DEBUGLOG(6, "reverse traversal, looking for shortest path (last_match_pos=%i)", last_match_pos);
01537          {   int candidate_pos = cur;
01538              int selected_matchLength = best_mlen;
01539              int selected_offset = best_off;
01540              while (1) {  /* from end to beginning */
01541                  int const next_matchLength = opt[candidate_pos].mlen;  /* can be 1, means literal */
01542                  int const next_offset = opt[candidate_pos].off;
01543                  DEBUGLOG(7, "pos %i: sequence length %i", candidate_pos, selected_matchLength);
01544                  opt[candidate_pos].mlen = selected_matchLength;
01545                  opt[candidate_pos].off = selected_offset;
01546                  selected_matchLength = next_matchLength;
01547                  selected_offset = next_offset;
01548                  if (next_matchLength > candidate_pos) break; /* last match elected, first match to encode */
01549                  assert(next_matchLength > 0);  /* can be 1, means literal */
01550                  candidate_pos -= next_matchLength;
01551          }   }
01552 
01553          /* encode all recorded sequences in order */
01554          {   int rPos = 0;  /* relative position (to ip) */
01555              while (rPos < last_match_pos) {
01556                  int const ml = opt[rPos].mlen;
01557                  int const offset = opt[rPos].off;
01558                  if (ml == 1) { ip++; rPos++; continue; }  /* literal; note: can end up with several literals, in which case, skip them */
01559                  rPos += ml;
01560                  assert(ml >= MINMATCH);
01561                  assert((offset >= 1) && (offset <= LZ4_DISTANCE_MAX));
01562                  opSaved = op;
01563                  if ( LZ4HC_encodeSequence(UPDATABLE(ip, op, anchor), ml, ip - offset, limit, oend) ) {  /* updates ip, op and anchor */
01564                      ovml = ml;
01565                      ovref = ip - offset;
01566                      goto _dest_overflow;
01567          }   }   }
01568      }  /* while (ip <= mflimit) */
01569 
01570 _last_literals:
01571      /* Encode Last Literals */
01572      {   size_t lastRunSize = (size_t)(iend - anchor);  /* literals */
01573          size_t llAdd = (lastRunSize + 255 - RUN_MASK) / 255;
01574          size_t const totalSize = 1 + llAdd + lastRunSize;
01575          if (limit == fillOutput) oend += LASTLITERALS;  /* restore correct value */
01576          if (limit && (op + totalSize > oend)) {
01577              if (limit == limitedOutput) { /* Check output limit */
01578                 retval = 0;
01579                 goto _return_label;
01580              }
01581              /* adapt lastRunSize to fill 'dst' */
01582              lastRunSize  = (size_t)(oend - op) - 1 /*token*/;
01583              llAdd = (lastRunSize + 256 - RUN_MASK) / 256;
01584              lastRunSize -= llAdd;
01585          }
01586          DEBUGLOG(6, "Final literal run : %i literals", (int)lastRunSize);
01587          ip = anchor + lastRunSize; /* can be != iend if limit==fillOutput */
01588 
01589          if (lastRunSize >= RUN_MASK) {
01590              size_t accumulator = lastRunSize - RUN_MASK;
01591              *op++ = (RUN_MASK << ML_BITS);
01592              for(; accumulator >= 255 ; accumulator -= 255) *op++ = 255;
01593              *op++ = (BYTE) accumulator;
01594          } else {
01595              *op++ = (BYTE)(lastRunSize << ML_BITS);
01596          }
01597          LZ4_memcpy(op, anchor, lastRunSize);
01598          op += lastRunSize;
01599      }
01600 
01601      /* End */
01602      *srcSizePtr = (int) (((const char*)ip) - source);
01603      retval = (int) ((char*)op-dst);
01604      goto _return_label;
01605 
01606 _dest_overflow:
01607 if (limit == fillOutput) {
01608      /* Assumption : ip, anchor, ovml and ovref must be set correctly */
01609      size_t const ll = (size_t)(ip - anchor);
01610      size_t const ll_addbytes = (ll + 240) / 255;
01611      size_t const ll_totalCost = 1 + ll_addbytes + ll;
01612      BYTE* const maxLitPos = oend - 3; /* 2 for offset, 1 for token */
01613      DEBUGLOG(6, "Last sequence overflowing (only %i bytes remaining)", (int)(oend-1-opSaved));
01614      op = opSaved;  /* restore correct out pointer */
01615      if (op + ll_totalCost <= maxLitPos) {
01616          /* ll validated; now adjust match length */
01617          size_t const bytesLeftForMl = (size_t)(maxLitPos - (op+ll_totalCost));
01618          size_t const maxMlSize = MINMATCH + (ML_MASK-1) + (bytesLeftForMl * 255);
01619          assert(maxMlSize < INT_MAX); assert(ovml >= 0);
01620          if ((size_t)ovml > maxMlSize) ovml = (int)maxMlSize;
01621          if ((oend + LASTLITERALS) - (op + ll_totalCost + 2) - 1 + ovml >= MFLIMIT) {
01622              DEBUGLOG(6, "Space to end : %i + ml (%i)", (int)((oend + LASTLITERALS) - (op + ll_totalCost + 2) - 1), ovml);
01623              DEBUGLOG(6, "Before : ip = %p, anchor = %p", ip, anchor);
01624              LZ4HC_encodeSequence(UPDATABLE(ip, op, anchor), ovml, ovref, notLimited, oend);
01625              DEBUGLOG(6, "After : ip = %p, anchor = %p", ip, anchor);
01626      }   }
01627      goto _last_literals;
01628 }
01629 _return_label:
01630 #if defined(LZ4HC_HEAPMODE) && LZ4HC_HEAPMODE==1
01631      FREEMEM(opt);
01632 #endif
01633      return retval;
01634 }
01635 
01636 }
